228	
229	      final P2PConfig p2PConfig = p2pConfigBuilder.build();
230	      syncConfigBuilder.isSyncEnabledDefault(p2PConfig.getNetworkConfig().isEnabled());
231	
232	      final StorageConfiguration storageConfiguration = storageConfigurationBuilder.build();
233	      // the storageConfiguration may change the dataStorage mode, so make sure any change is
234	      // reflected in the sync config builder
235	      syncConfigBuilder.fetchAllHistoricBlocks(
236	          storageConfiguration.getDataStorageMode().storesAllBlocks());
237	
238	      final SyncConfig syncConfig = syncConfigBuilder.build();
239	
240	      final long maxAllowedBatchSize =
241	          spec.getNetworkingConfigDeneb()
242	              .map(NetworkingSpecConfigDeneb::getMaxRequestBlocksDeneb)
243	              .orElse(spec.getNetworkingConfig().getMaxRequestBlocks());
244	
245	      if (syncConfig.getForwardSyncBatchSize() > maxAllowedBatchSize) {
246	        throw new InvalidConfigurationException(
247	            "Forward sync batch size cannot be greater than " + maxAllowedBatchSize);
248	      }
249	
250	      if (syncConfig.getHistoricalSyncBatchSize() > maxAllowedBatchSize) {
251	        throw new InvalidConfigurationException(
252	            "Historical sync batch size cannot be greater than " + maxAllowedBatchSize);
253	      }
254	
255	      // Check for invalid config settings
256	      if (syncConfig.isReconstructHistoricStatesEnabled()
257	          && eth2NetworkConfiguration.getNetworkBoostrapConfig().getGenesisState().isEmpty()) {
258	        throw new InvalidConfigurationException(
259	            "Genesis state required when reconstructing historic states");
260	      }
261	
262	      if (syncConfig.isReconstructHistoricStatesEnabled()) {
263	        if (!storageConfiguration.getDataStorageMode().storesFinalizedStates()
264	            || !storageConfiguration.getDataStorageMode().storesAllBlocks()) {
265	          throw new InvalidConfigurationException(
266	              "Cannot reconstruct historic states without using ARCHIVE data storage mode");
267	        }
268	      }
269	
270	      return new TekuConfiguration(
271	          eth2NetworkConfiguration,
272	          spec,
273	          storageConfiguration,
274	          weakSubjectivityBuilder.build(),
275	          validatorConfig,
276	          powchainConfigBuilder.build(),
277	          executionLayerConfigBuilder.build(),
278	          interopConfigBuilder.build(),
279	          dataConfig,
280	          p2PConfig,
281	          syncConfig,
282	          restApiBuilder.build(),
283	          metricsConfigBuilder.build(),
284	          storeConfigBuilder.build(),
285	          natConfigBuilder.build(),
286	          validatorRestApiConfigBuilder.build(),
287	          beaconChainControllerFactory);
288	    }
